text:
This analysis examines coffee ratings based on data from TidyTuesday (2020-07-07). This is an older dataset that contains variables for various coffee characteristics, and in my analysis I will investigate which of these are most strongly correlated with a coffee’s overall rating.



coffee_ratings &lt;- readr::read_csv('https://raw.githubusercontent.com/rfordatascience/tidytuesday/main/data/2020/2020-07-07/coffee_ratings.csv')





coffee_characteristics &lt;- coffee_ratings |&gt;
  dplyr::select(
    total_cup_points,
    aroma,
    flavor,
    aftertaste,
    acidity,
    body,
    balance,
    uniformity,
    clean_cup,
    sweetness,
    cupper_points
  )


correlations &lt;- coffee_characteristics |&gt;
  cor(use = "complete.obs") |&gt;
  as.data.frame() |&gt;
  dplyr::select(total_cup_points) |&gt;
  dplyr::rename(correlation = total_cup_points) |&gt;
  tibble::rownames_to_column("characteristic") |&gt;
  dplyr::filter(characteristic != "total_cup_points") |&gt;
  dplyr::arrange(correlation)





library(ggplot2)

ggplot(
  correlations,
  aes(
    x = correlation,
    y = reorder(characteristic, correlation)
  )
) +
  geom_col(fill = "blue") +
  labs(
    title = "Which Characteristics Relate Most to Overall Coffee Rating (cupper points)?",
    subtitle = "Correlation with total cupper points",
    x = "Correlation with total cupper points",
    y = "Coffee characteristic"
  ) +
  theme_minimal()

